import { useEffect, useState } from 'react';
import Launchpad from './pages/Launchpad';
import Demo from './pages/demo/Demo';
import Tenant from './pages/tenant/Tenant';

// Hash routing so static hosting needs no rewrite rules. Point client iPads at #/demo.
const currentRoute = () => {
  const hash = window.location.hash;
  if (hash.startsWith('#/tenant')) return 'tenant';
  if (hash.startsWith('#/demo')) return 'demo';
  return 'launchpad';
};

/** Routes between the internal launchpad, the client-facing JAIME demo, and tenant settings. */
export default function App() {
  const [route, setRoute] = useState(currentRoute);

  useEffect(() => {
    const onHash = () => setRoute(currentRoute());
    window.addEventListener('hashchange', onHash);
    return () => window.removeEventListener('hashchange', onHash);
  }, []);

  if (route === 'tenant') return <Tenant />;
  if (route === 'demo') return <Demo />;
  return <Launchpad />;
}
